<?php declare(strict_types=1); $token = trim((string) ($_GET['token'] ?? '')); ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redefinir senha | NyxCloud</title><link rel="stylesheet" href="../assets/css/login.css"></head><body><main class="auth-shell"><section class="form-panel" style="grid-column:1/-1"><div class="form-card"><header class="form-header"><p class="eyebrow">Seguranca</p><h2>Nova senha</h2><p>Escolha senha com pelo menos 8 caracteres.</p></header><form class="login-form" id="resetForm"><input type="hidden" name="token" value="<?= htmlspecialchars($token, ENT_QUOTES, 'UTF-8') ?>"><div class="field-group"><label for="senha">Nova senha</label><div class="input-wrap"><input id="senha" name="senha" type="password" minlength="8" autocomplete="new-password" required></div></div><div class="field-group"><label for="confirmacao">Confirmar senha</label><div class="input-wrap"><input id="confirmacao" type="password" minlength="8" autocomplete="new-password" required></div></div><button class="submit-button" type="submit"><span class="button-label">Salvar senha</span></button><p class="form-message" id="resetMessage" role="alert"></p></form><p class="security-note"><a href="index.php">Voltar ao login</a></p></div></section></main><script>
document.getElementById('resetForm').addEventListener('submit', async (event) => { event.preventDefault(); const form=event.currentTarget, senha=form.senha.value, msg=document.getElementById('resetMessage'); if(senha.length<8||senha!==document.getElementById('confirmacao').value){msg.textContent='Senhas nao conferem ou possuem menos de 8 caracteres.';return;} const r=await fetch('api/reset-password.php',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({token:form.token.value,senha})}); const d=await r.json(); msg.textContent=d.message; if(r.ok)setTimeout(()=>location.href='index.php',1200); });
</script></body></html>
